-- Test fixture ONLY. Never execute this file against a customer SCADA database.
-- Deliberately no last_update indexes; customer index availability is unknown.
CREATE TABLE public.alarmhistory (
    id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    al_start_time timestamp without time zone, al_start_time_ms integer,
    al_norm_time timestamp without time zone, al_norm_time_ms integer,
    al_ack_time timestamp without time zone, al_ack_time_ms integer,
    al_event_time timestamp without time zone, al_event_time_ms integer,
    al_ack boolean, al_active boolean, al_ack_req boolean, al_deleted boolean,
    al_tag text, al_message text, al_selection text, al_station text,
    al_tag_value varchar, al_prev_tag_value varchar, al_custom1 text,
    al_group integer, al_priority integer, al_type integer,
    al_user text, al_user_full text, al_user_comment text,
    last_update timestamp without time zone, last_update_ms integer
);
CREATE TABLE public.eventhistory (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ev_type integer,
    ev_time timestamp without time zone, ev_time_ms integer,
    ev_info text, ev_source text, ev_user text, ev_user_full text,
    ev_message text, ev_station text, ev_comment text,
    ev_deleted boolean, ev_value varchar, ev_prev_value varchar,
    last_update timestamp without time zone, last_update_ms integer
);
